package cn.videostudy.api;
import cn.videostudy.cloud.CloudDocumentStore;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.client.*;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import java.util.*;
@Service
@Profile("sqlite")
public class LocalSyncService {
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(LocalSyncService.class);
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final CourseSnapshotStore snapshots;private final String url,token;
 public record State(long revision,String hash){}
 public LocalSyncService(JdbcTemplate jdbc,ObjectMapper json,@Value("${framewise.sync.url:}") String url,@Value("${framewise.sync.token:}") String token){this.jdbc=jdbc;this.json=json;this.snapshots=new CourseSnapshotStore(jdbc,json);this.url=url;this.token=token;}
 private RestClient client(){if(url.isBlank()||token.length()<32)throw new IllegalArgumentException("sync_not_configured");var uri=java.net.URI.create(url);if(uri.getHost()==null||uri.getUserInfo()!=null||(!uri.getScheme().equals("https")&&!(uri.getScheme().equals("http")&&Set.of("127.0.0.1","localhost","cloud-api").contains(uri.getHost()))))throw new IllegalArgumentException("sync_invalid_server");var factory=new SimpleClientHttpRequestFactory();factory.setConnectTimeout(3000);factory.setReadTimeout(30000);return RestClient.builder().baseUrl(url).requestFactory(factory).defaultHeader("X-Framewise-Sync",token).build();}
 public Map<String,Object> status(){return Map.of("storage","sqlite","configured",!url.isBlank()&&token.length()>=32,"syncedCourses",jdbc.queryForObject("SELECT COUNT(*) FROM local_sync_state",Integer.class),"localCourses",jdbc.queryForObject("SELECT COUNT(*) FROM transcription_jobs",Integer.class),"filesIncluded",false);}
 public Map<String,Object> connect(){return action("connection","all",()->{var c=client();var health=c.get().uri("/api/cloud-sync/health").retrieve().body(Map.class);if(health==null||!"mysql".equals(health.get("storage")))throw new IllegalArgumentException("sync_invalid_server");var documents=c.get().uri("/api/cloud-sync/documents").retrieve().body(CloudDocumentStore.Summary[].class);return Map.of("connected",true,"storage","mysql","documents",documents==null?List.of():Arrays.asList(documents));});}
 private State state(String id){return jdbc.query("SELECT remote_revision,base_hash FROM local_sync_state WHERE course_id=?",(r,n)->new State(r.getLong(1),r.getString(2)),id).stream().findFirst().orElse(null);}
 private void remember(String id,long revision,String hash){if(jdbc.update("UPDATE local_sync_state SET remote_revision=?,base_hash=?,synced_at=strftime('%Y-%m-%d %H:%M:%f','now') WHERE course_id=?",revision,hash,id)==0)jdbc.update("INSERT INTO local_sync_state(course_id,remote_revision,base_hash) VALUES (?,?,?)",id,revision,hash);}
 public Map<String,Object> push(String id){CourseSnapshotStore.validId(id);return action("upload",id,()->{var snapshot=snapshots.exportCourse(id);String hash=CourseSnapshotStore.hash(json,snapshot);var state=state(id);var result=client().put().uri("/api/cloud-sync/documents/"+id).body(Map.of("expectedRevision",state==null?0:state.revision(),"snapshot",snapshot)).retrieve().body(CloudDocumentStore.Document.class);if(result==null||!hash.equals(result.hash()))throw new IllegalArgumentException("sync_invalid_reply");remember(id,result.revision(),hash);return Map.of("id",id,"revision",result.revision(),"result","uploaded");});}
 public Map<String,Object> pull(String id){CourseSnapshotStore.validId(id);return action("download",id,()->{var remote=client().get().uri("/api/cloud-sync/documents/"+id).retrieve().body(CloudDocumentStore.Document.class);if(remote==null||remote.snapshot()==null||!id.equals(remote.snapshot().courseId())||remote.revision()<0||!CourseSnapshotStore.hash(json,remote.snapshot()).equals(remote.hash()))throw new IllegalArgumentException("sync_invalid_reply");CourseSnapshotStore.validate(remote.snapshot());
  var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.executeWithoutResult(status->{var saved=state(id);boolean exists=jdbc.queryForObject("SELECT COUNT(*) FROM transcription_jobs WHERE id=?",Integer.class,id)>0;String localHash=exists?CourseSnapshotStore.hash(json,snapshots.exportCourse(id)):null;if(Objects.equals(localHash,remote.hash())){remember(id,remote.revision(),remote.hash());return;}if(exists&&(saved==null||!saved.hash().equals(localHash)))throw new IllegalArgumentException("local_changes");snapshots.restore(remote.snapshot(),localHash);remember(id,remote.revision(),remote.hash());});return Map.of("id",id,"revision",remote.revision(),"result","downloaded");});}
 private <T>T action(String stage,String id,java.util.function.Supplier<T> call){long started=System.nanoTime();String request=UUID.randomUUID().toString();try{T result=call.get();log.info("Local sync task={} request={} stage={} result=completed elapsed_ms={}",id,request,stage,(System.nanoTime()-started)/1000000);return result;}catch(RuntimeException e){String code=e instanceof IllegalArgumentException?Objects.toString(e.getMessage(),"sync_failed"):e instanceof RestClientResponseException response?(response.getStatusCode().value()==401?"sync_unauthorized":response.getStatusCode().value()==409?"sync_conflict":response.getStatusCode().value()==404?"course_not_found":"sync_server_error"):"sync_unavailable";if(!Set.of("sync_not_configured","sync_invalid_server","sync_invalid_reply","local_changes","invalid_snapshot","course_busy","course_not_found","sync_unauthorized","sync_conflict","sync_server_error","sync_unavailable").contains(code))code="sync_failed";log.warn("Local sync task={} request={} stage={} result={} type={} elapsed_ms={}",id,request,stage,code,e.getClass().getSimpleName(),(System.nanoTime()-started)/1000000);throw new IllegalArgumentException(code);}}
}
